from math import fsum, sqrt, isfinite
from random import Random

def mean_standard_error(values):
    if type(values) is not list or not 2 <= len(values) <= 100000:
        raise ValueError("expected a list of 2..100000 bounded finite real values")
    if any(type(x) not in (int,float) or abs(x) > 1000000 or not isfinite(x) for x in values):
        raise ValueError("expected finite int/float values with abs(x)<=1000000, excluding bool")
    mean = fsum(values) / len(values)
    sample_variance = fsum((x-mean)**2 for x in values) / (len(values)-1)
    return mean, sqrt(sample_variance / len(values))

def simulate_die(n, seed):
    if type(n) is not int or not 2 <= n <= 100000 or type(seed) is not int:
        raise ValueError("expected integer n in [2,100000] and integer seed")
    rng = Random(seed)
    values = [rng.randrange(1,7) for _ in range(n)]
    return mean_standard_error(values)

estimate, estimated_se = simulate_die(10000, 2026)
print(f"{estimate:.6f}")
print(f"{estimated_se:.6f}")
print(f"{sqrt((35/12)/10000):.6f}")
print(simulate_die(10000, 2026) == (estimate, estimated_se))
